SELECT  FROM ca_message WHERE receiver_user_id=#{userId}
AND title LIKE CONCAT('%',#{q.keyword},'%')
AND read_flag=#{q.status}
AND message_type=#{q.messageType}
AND create_time >= #{q.beginTime}
AND create_time < #{q.endTime}
ORDER BY message_id DESC

